async function fletchAll(productText){
  await bot.dismissBlockingUI();
  const knife=sdk.findInventoryItem(/knife/i);
  const logs=sdk.getInventory().filter(i=>/logs/i.test(i.name));
  if(!logs.length) return 'no logs';
  const count=logs.length;
  await sdk.sendUseItemOnItem(knife.slot, logs[0].slot);
  await sdk.waitForCondition(s=>s.dialog.isOpen,5000);
  const d=sdk.getDialog();
  // find label component matching product, then its "Make X" is 3 before it
  const idx=d.allComponents.findIndex(c=>c.text.toLowerCase().includes(productText.toLowerCase()));
  if(idx<0) return {err:'no product', comps:d.allComponents.map(c=>c.text)};
  const makeX=d.allComponents[idx-3];
  await sdk.sendClickComponent(makeX.id);
  await sdk.waitForTicks(2);
  await sdk.sendCountDialog(count);
  return {clicked:makeX.id, count};
}
