async function grind(pattern, ms) {
  const t0=Date.now(), x0=sdk.getSkillXp('Strength');
  let cur=-1;
  while (Date.now()-t0 < ms) {
    const st=sdk.getState();
    const me=st.player;
    const tn = st.nearbyNpcs.find(n=>n.index===cur);
    const alive = tn && (tn.health?.current ?? 1) > 0;
    const attacking = st.combat?.targetIndex === cur && alive;
    if (!alive || me.animId===-1 && !attacking) {
      const tgt = st.nearbyNpcs
        .filter(n=>pattern.test(n.name) && n.optionsWithIndex.some(o=>/^attack$/i.test(o.text)) && (n.health?.current ?? 1)>0)
        .sort((a,b)=>a.distance-b.distance)[0];
      if (tgt) { cur=tgt.index; await sdk.sendInteractNpc(tgt.index, tgt.optionsWithIndex.find(o=>/^attack$/i.test(o.text)).opIndex); }
    }
    await sdk.waitForTicks(1);
  }
  const dt=(Date.now()-t0)/1000, g=sdk.getSkillXp('Strength')-x0;
  return {dt, g, score: g/dt*60/200};
}
