async function testLane(sx,sz,dx,dz,n){
  await bot.walkTo(sx,sz,2); const visited=[];
  let x=sdk.getState().player.worldX, z=sdk.getState().player.worldZ;
  for(let i=0;i<n;i++){ await sdk.sendWalk(x+dx,z+dz); await sdk.waitForTicks(1); const p=sdk.getState().player; if(p.worldX===x&&p.worldZ===z) break; x=p.worldX; z=p.worldZ; visited.push([x,z]); }
  return {start:[sx,sz], len:visited.length, end:visited[visited.length-1]};
}
